void mainImage(out vec4 Q, in vec2 U) {
    R = iResolution.xy;
    if (iFrame%4>0) {discard;return;}
    vec3 p = vec3(.5*R3.xy,-1.9*R3.x);
    vec3 d = normalize(vec3(2.*(U-.5*R)/R.y,2.));
    p -= .5*R3;
    if (iMouse.z>0.) {
    p.yz *= ei(-iMouse.y/R.x*6.2);
    d.yz *= ei(-iMouse.y/R.x*6.2);
    p.xz *= ei(iMouse.x/R.x*6.2);
    d.xz *= ei(iMouse.x/R.x*6.2);
    } else {
        p.yz *= ei(.2*sin(iTime));
        d.yz *= ei(.2*sin(iTime));
        p.xz *= ei(.2*sin(iTime));
        d.xz *= ei(.2*sin(iTime));
    }
    p += .5*R3;
    p += d*1.0000001*cube(p,d,vec3(-R3.xy,0),vec3(2,2,1)*R3);

    vec3 no = vec3(0);
    vec3 nd = vec3(0);
    Q = vec4(0,0,0,0);
    float e = 1.;
        for (float i = 0.; i < 5.*N*N; i++) {
        if (p.z<0.||p.z>N*N) break;
        vec4 x = 1.*LN(iChannel0,p);
        vec4 y = 1.*LN(iChannel1,p);
        p += d;
        Q += .05*(abs(x)+abs(y));
    }
    Q = pow(Q,vec4(.8));
  }

